"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { useMorphoUserVaultPosition } from "hooks/morpho";
import { useState } from "react";
import { ArrowRight, X } from "react-feather";
import { Button, Flex, Input, SpinningLoader, Text, styled as uiStyled, useSporeColors } from "ui/src";
import { Modal } from "uniswap/src/components/modals/Modal";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useAccount } from "wagmi";
import { useEarnContext } from "../ContextProvider";
const TOKEN_PRICES_USD = {
  USDC: 1,
  WETH: 3500,
  ETH: 3500
};
function getTokenPriceUsd(symbol) {
  return TOKEN_PRICES_USD[symbol.toUpperCase()] ?? 1;
}
const CloseIcon = uiStyled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = uiStyled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const InputCard = uiStyled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing16",
  gap: "$gap12",
  width: "100%",
  borderWidth: 1,
  borderColor: "transparent",
  transition: "border-color 0.2s ease-in-out",
  variants: {
    focused: {
      true: {
        borderColor: "$neutral3"
      }
    }
  }
});
const InputField = uiStyled(Input, {
  unstyled: true,
  backgroundColor: "transparent",
  borderWidth: 0,
  outlineStyle: "none",
  padding: 0,
  fontSize: "$h2",
  color: "$neutral1",
  width: "100%",
  textAlign: "left",
  fontFamily: "$body3"
});
const MaxButton = uiStyled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$rounded8",
  padding: "$spacing4",
  paddingHorizontal: "$spacing8",
  cursor: "pointer",
  hoverStyle: { opacity: 0.8 }
});
const VaultInfoCard = uiStyled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing16",
  gap: "$gap12",
  width: "100%",
  marginTop: "$spacing12",
  marginBottom: "$spacing24"
});
const InfoRow = uiStyled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%"
});
const SubmitButton = uiStyled(Button, {
  width: "100%",
  py: "$spacing24"
});
const LabelText = uiStyled(Text, {
  variant: "body3",
  color: "$neutral2",
  $md: {
    variant: "body4"
  }
});
const ValueText = uiStyled(Text, {
  color: "$neutral1"
});
export default function DepositWithdrawPopupModal({
  vault,
  isOpen,
  onClose,
  type
}) {
  const colors = useSporeColors();
  const { transactionAmount, setTransactionAmount, setTransactionStep } = useEarnContext();
  const [isFocused, setIsFocused] = useState(false);
  const { address: userAddress } = useAccount();
  const chainId = UniverseChainId.Mainnet;
  const { data: userPosition, isLoading: isLoadingPosition } = useMorphoUserVaultPosition(
    vault?.address,
    userAddress,
    chainId
  );
  const amount = transactionAmount;
  const setAmount = setTransactionAmount;
  if (!vault) return null;
  const isAmountValid = amount.length > 0 && parseFloat(amount) > 0;
  const isDeposit = type === "deposit";
  const title = isDeposit ? "Deposit" : "Withdraw";
  const handleActionClick = () => {
    if (isAmountValid) {
      setTransactionStep("review");
    }
  };
  const handleClose = () => {
    onClose();
  };
  const walletBalance = userPosition?.walletBalanceFormatted ?? "0";
  const currentPosition = Number(userPosition?.assetsValueFormatted ?? "0");
  const maxWithdraw = userPosition?.maxWithdrawFormatted ?? "0";
  const newPosition = isDeposit ? currentPosition + parseFloat(amount || "0") : Math.max(0, currentPosition - parseFloat(amount || "0"));
  const maxAmount = isDeposit ? walletBalance : maxWithdraw;
  const handleMaxClick = () => {
    setAmount(maxAmount);
  };
  return <Modal
    name="DepositWithdrawModal"
    isModalOpen={isOpen}
    onClose={handleClose}
    backgroundColor={colors.surface1?.val ?? "#1a1a1a"}
    maxWidth={480}
    padding="$spacing24"
  >
      {
    /* Header */
  }
      <ModalHeader>
        <Text variant="heading3" color="$neutral1">
          {title}
        </Text>
        <CloseIcon onPress={handleClose}>
          <X size={24} color={colors.neutral2?.val ?? "#888"} />
        </CloseIcon>
      </ModalHeader>

      {
    /* Input Section */
  }
      <Flex flexDirection="row" justifyContent="space-between" mb="$spacing8" px="$spacing4">
        <Text variant="body2" color="$neutral2">
          {title} {vault.token.symbol}
        </Text>
        <Flex flexDirection="row" gap="$gap8" alignItems="center">
          {isLoadingPosition ? <SpinningLoader size={16} /> : <Text variant="body2" color="$neutral2">
              {isDeposit ? walletBalance : maxWithdraw} {vault.token.symbol}
            </Text>}
          <MaxButton onPress={handleMaxClick}>
            <Text variant="buttonLabel4" color="$neutral2">
              MAX
            </Text>
          </MaxButton>
        </Flex>
      </Flex>

      <InputCard focused={isFocused}>
        <Flex flexDirection="row" alignItems="center" justifyContent="space-between">
          <InputField
    placeholder="0.00"
    autoFocus
    placeholderTextColor="$neutral3"
    value={amount}
    onChangeText={setAmount}
    onFocus={() => setIsFocused(true)}
    onBlur={() => setIsFocused(false)}
  />
          <Flex
    flexDirection="row"
    alignItems="center"
    gap="$gap8"
    backgroundColor="$surface1"
    px="$spacing8"
    py="$spacing4"
    borderRadius="$roundedFull"
  >
            <PortfolioLogo
    chainId={chainId}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name}
    images={[getTokenLogoUrl(vault.token.address)]}
    size={24}
  />
            <Text variant="buttonLabel1" color="$neutral1">
              {vault.token.symbol}
            </Text>
          </Flex>
        </Flex>
        <Text variant="body3" color="$neutral2">
          ${(parseFloat(amount || "0") * getTokenPriceUsd(vault.token.symbol)).toFixed(2)}
        </Text>
      </InputCard>

      {
    /* Vault Info Section */
  }
      <VaultInfoCard>
        <Flex flexDirection="row" alignItems="center" gap="$gap12" mb="$spacing8">
          <PortfolioLogo
    chainId={chainId}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name}
    images={[getTokenLogoUrl(vault.token.address)]}
    size={40}
  />
          <Flex flexDirection="column">
            <LabelText variant="body1" color="$neutral1">
              {vault.name}
            </LabelText>
            <LabelText variant="body2" color="$neutral2">
              {vault.symbol}
            </LabelText>
          </Flex>
        </Flex>

        <InfoRow>
          <LabelText>
            My Position ({vault.token.symbol})
          </LabelText>
          <Flex flexDirection="row" alignItems="center" gap="$gap4">
            <ValueText>
              {currentPosition.toFixed(vault.token.decimals <= 6 ? 2 : 6)}
            </ValueText>
            <ArrowRight size={12} color={colors.neutral2?.val ?? "#888"} />
            <ValueText>
              {newPosition.toFixed(vault.token.decimals <= 6 ? 2 : 6)}
            </ValueText>
          </Flex>
        </InfoRow>

        <InfoRow>
          <LabelText>
            Fee
          </LabelText>
          <ValueText>
            {vault.feePercent.toFixed(1)}%
          </ValueText>
        </InfoRow>

        <InfoRow>
          <LabelText>
            Share Price
          </LabelText>
          <ValueText>
            {vault.sharePrice.toFixed(vault.token.decimals <= 6 ? 4 : 8)} {vault.token.symbol}
          </ValueText>
        </InfoRow>
      </VaultInfoCard>

      {
    /* Action Button */
  }
      <SubmitButton size="large" emphasis="primary" disabled={!isAmountValid} onPress={handleActionClick}>
        {isAmountValid ? title : "Enter an amount"}
      </SubmitButton>
    </Modal>;
}
